  ('shrm-scp', 'workforce-hr-strategist')
) v(cert_slug, role_slug)
join public.certifications c on c.slug = v.cert_slug
join public.roles r on r.slug = v.role_slug
on conflict do nothing;
select distinct cr.certification_id, r.practice_id from public.certification_roles cr join public.roles r on r.id = cr.role_id
on conflict do nothing;

-- Dropdown and checklist options
on conflict (set_key, value) do update set label = excluded.label, sort = excluded.sort, active = true;
update public.option_sets set active = false where (set_key, value) not in (('hear_about', 'referral'), ('hear_about', 'event'), ('hear_about', 'linkedin'), ('hear_about', 'claude_partner_network'), ('hear_about', 'other'), ('time_zones', 'ET'), ('time_zones', 'CT'), ('time_zones', 'MT'), ('time_zones', 'PT'), ('time_zones', 'AKT'), ('time_zones', 'HT'), ('time_zones', 'other'), ('industries', 'nonprofit'), ('industries', 'government'), ('industries', 'education'), ('industries', 'healthcare'), ('industries', 'financial_services'), ('industries', 'insurance'), ('industries', 'professional_services'), ('industries', 'trades_construction'), ('industries', 'technology'), ('industries', 'hospitality'), ('industries', 'faith_based'), ('industries', 'other'), ('client_types', 'fortune_500'), ('client_types', 'mid_market'), ('client_types', 'small_business'), ('client_types', 'startups'), ('client_types', 'public_sector'), ('client_types', 'nonprofits'), ('tools', 'claude'), ('tools', 'chatgpt'), ('tools', 'microsoft_copilot'), ('tools', 'gemini'), ('tools', 'n8n'), ('tools', 'zapier'), ('tools', 'make'), ('tools', 'notion'), ('tools', 'airtable'), ('tools', 'hubspot'), ('tools', 'salesforce'), ('tools', 'microsoft_365'), ('tools', 'google_workspace'), ('tools', 'aws'), ('tools', 'azure'), ('tools', 'google_cloud'), ('tools', 'python'), ('tools', 'sql'), ('tools', 'power_bi'), ('tools', 'canva'), ('tools', 'lms_platforms'), ('tools', 'other'), ('ai_usage_frequency', 'never'), ('ai_usage_frequency', 'monthly'), ('ai_usage_frequency', 'weekly'), ('ai_usage_frequency', 'daily'), ('ai_usage_frequency', 'core'), ('proficiency', '1'), ('proficiency', '2'), ('proficiency', '3'), ('proficiency', '4'), ('hours_per_week', 'under_10'), ('hours_per_week', '10_20'), ('hours_per_week', '20_30'), ('hours_per_week', '30_40'), ('hours_per_week', '40_plus'), ('engagement_types', 'project_based'), ('engagement_types', 'part_time_retainer'), ('engagement_types', 'embedded'), ('engagement_types', 'facilitation_training'), ('engagement_types', 'rfp_bench'), ('work_settings', 'remote'), ('work_settings', 'onsite_houston'), ('work_settings', 'onsite_dmv'), ('work_settings', 'travel'), ('travel_frequency', 'rarely'), ('travel_frequency', 'sometimes'), ('travel_frequency', 'often'), ('travel_frequency', 'frequently'), ('operating_as', 'sole_proprietor'), ('operating_as', 'entity'), ('operating_as', 'not_set_up'), ('liability_insurance', 'yes'), ('liability_insurance', 'no'), ('liability_insurance', 'not_yet'), ('ai_cert_commitment', 'yes'), ('ai_cert_commitment', 'no'), ('ai_cert_commitment', 'already_have'), ('team_size', '2_5'), ('team_size', '6_10'), ('team_size', '11_25'), ('team_size', '26_50'), ('team_size', '50_plus'), ('business_certs', 'mbe'), ('business_certs', 'wbe'), ('business_certs', 'wosb'), ('business_certs', 'edwosb'), ('business_certs', 'sbe'), ('business_certs', 'dbe'), ('business_certs', 'hub'), ('business_certs', 'hubzone'), ('business_certs', 'sdvosb'), ('business_certs', '8a'), ('business_certs', 'other'));

-- Statuses
on conflict (key) do update set label = excluded.label, description = excluded.description, sort = excluded.sort, is_terminal = excluded.is_terminal;

-- Scorecard criteria
on conflict (scorecard_type, key) do update set label = excluded.label, sort = excluded.sort, active = true;

-- Onboarding checklist steps
on conflict (key) do update set label = excluded.label, sort = excluded.sort, active = true;
update public.onboarding_step_templates set active = false where key not in ('mou-sent', 'mou-signed', 'company-alias-email-created', 'anthropic-academy-account-created', 'coursework-registered', 'coursework-complete', 'exam-prep-meeting', 'exam-scheduled', 'subcontractor-agreement-and-w-9-sent', 'certification-complete', 'contractor-documents-complete', 'final-review', 'portal-access-granted', 'orientation-complete');

-- Settings
on conflict (key) do update set value = excluded.value, description = excluded.description, updated_at = now();

-- Admin allowlist (adds only; deactivate admins in the database)
on conflict (email) do update set active = true;

commit;
